const n=`# -*- coding: utf-8 -*-
"""python stat1-preflight.py morning.json results.json   |   --schema"""
import base64
import gzip
import hashlib
import json
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile

"""Portable check of a coaching result against the supplied morning index."""
import datetime
import json
import math
import re


def coaching_check(morning, text, runtime, spec):
    errors = []
    section, index = "file", -1

    def issue(code, path="", severity="error"):
        full_path = path or section
        if index >= 0:
            full_path = f"{section}[{index}]" + (f".{path}" if path else "")
        errors.append(dict(section=section, index=index, code=code, path=full_path, severity=severity))

    def result(status):
        return dict(status=status, version=spec["coachingRules"], issues=errors,
                    scope="Supplied morning snapshot. Live conflicts, formal assessments and save are checked on the device.")

    def rows(value):
        return value if isinstance(value, list) else []

    def obj(value):
        return value if isinstance(value, dict) else {}

    def txt(value, maximum=16000):
        return isinstance(value, str) and bool(value.strip()) and len(value.encode("utf-16-le", "surrogatepass")) // 2 <= maximum

    def num(value):
        return type(value) in (int, float) and math.isfinite(value)

    def points(value):
        return isinstance(value, list) and len(value) == 2 and all(num(n) for n in value) and 0 <= value[0] <= value[1] and value[1] > 0

    def day(value):
        try:
            return isinstance(value, str) and datetime.date.fromisoformat(value).isoformat() == value
        except ValueError:
            return False

    def timestamp(value):
        try:
            return txt(value, 50) and bool(re.search(r"(?:Z|[+-]\\d\\d:\\d\\d)$", value)) and datetime.datetime.fromisoformat(value.replace("Z", "+00:00")).tzinfo is not None
        except ValueError:
            return False

    def distinct(values):
        return len(set(map(repr, values))) == len(values)

    def bad_text(value):
        if isinstance(value, str):
            return "\\ufffd" in value or bool(re.search(spec["mathPattern"], value))
        if isinstance(value, (list, dict)):
            return any(map(bad_text, value.values() if isinstance(value, dict) else value))
        return False

    try:
        content = text.strip()
        fenced = re.fullmatch(r"\`\`\`(?:json)?\\s*([\\s\\S]*?)\\s*\`\`\`", content, re.IGNORECASE)
        packet = json.loads(fenced[1] if fenced else content, parse_constant=lambda x: (_ for _ in ()).throw(ValueError(x)))
    except (ValueError, TypeError):
        packet = None
    sections = spec["coachingSections"]
    lookup = obj(morning.get("lookup"))
    if morning.get("format") != spec["morningFormat"] or morning.get("subject") != "math" or not txt(morning.get("source"), 160) or not isinstance(morning.get("lookup"), dict):
        issue("FORMAT")
        return result("invalid")
    contract = obj(morning.get("contract"))
    if contract.get("rules") != spec["coachingRules"] or contract.get("verifier_hash") != runtime:
        issue("TOOL_VERSION")
        return result("invalid")
    packet = obj(packet)
    if (packet.get("subject", "math") != "math" or packet.get("format") != spec["resultFormat"] or
            packet.get("source") != morning["source"] or not any(rows(packet.get(k)) for k in sections) or
            len(text.encode("utf-16-le", "surrogatepass")) // 2 > 2000000 or
            not all(isinstance(lookup.get(k), list) for k in ("problems", "answers", "reviews", "abilities", "topics"))):
        issue("FORMAT")
        return result("invalid")
    for key in sections:
        if key in packet and (not isinstance(packet[key], list) or len(packet[key]) > (64 if key == "problems" else 96)):
            issue("SHAPE", key)
    if errors:
        return result("invalid")
    abilities, topics = lookup["abilities"], lookup["topics"]
    known_problems = dict(lookup["problems"])
    known_answers = {answer[0]: answer for answer in lookup["answers"]}
    new_problems, new_answers = {}, {}
    declared = {a["ref"] for a in rows(packet.get("answers")) if txt(obj(a).get("ref"), 160)}
    observed_marks = ("correct", "partial", "incorrect")
    temp = re.compile(r"[A-Za-z][A-Za-z0-9_-]{0,79}", re.ASCII)

    def unknown(ref, path, prefix):
        if isinstance(ref, str) and ref.startswith(prefix):
            issue("DEVICE", path, "warning")
        else:
            issue("ID", path)

    def problem(ref, path):
        if isinstance(ref, str):
            parts = known_problems.get(ref, new_problems.get(ref))
            if parts is not None:
                return parts
        unknown(ref, path, "P/")
        return None

    def link(value, path, observed=False, prior=False):
        value = obj(value)
        aid, part = value.get("answer"), value.get("part")
        if not txt(aid, 160) or not txt(part, 200):
            issue("SHAPE", path)
            return
        answer = new_answers.get(aid, known_answers.get(aid))
        if answer is None:
            if prior or aid not in declared:
                unknown(aid, path + ".answer", "A/")
        elif part not in answer[3 if observed else 2]:
            issue("ID", path + ".part")

    def check_subjects(value, path=""):
        if isinstance(value, list):
            for i, item in enumerate(value):
                check_subjects(item, f"{path}[{i}]")
        elif isinstance(value, dict):
            if value.get("subject", "math") != "math":
                issue("SUBJECT", f"{path}.subject" if path else "subject")
            for key, child in value.items():
                check_subjects(child, f"{path}.{key}" if path else key)

    for section in sections:
        entries = rows(packet.get(section))
        refs = [obj(entry).get("ref") for entry in entries]
        prefix = {"answers": "A/", "reviews": "R/", "updates": "U/"}.get(section, "")
        for index, x in enumerate(entries):
            if not isinstance(x, dict):
                issue("SHAPE")
                continue
            check_subjects(x)
            if x.get("subject", "math") != "math":
                continue
            if bad_text(x):
                issue("TEXT")
                continue
            ref, previous = x.get("ref"), len(errors)
            if (section != "ongoing" or "ref" in x) and (
                    not isinstance(ref, str) or not (temp.fullmatch(ref) or prefix and ref.startswith(prefix) and len(ref) <= 160)):
                issue("SHAPE", "ref")
                continue
            if isinstance(ref, str) and refs.count(ref) > 1:
                issue("DUPLICATE", "ref")
                continue
            if section == "problems":
                ids = [item if isinstance(item, str) else obj(item).get("id") if txt(obj(item).get("label"), 120) else None for item in rows(x.get("parts"))]
                if not txt(x.get("text")) or "title" in x and not txt(x["title"], 120) or not 1 <= len(ids) <= 24 or ids != [f"q{i+1}" for i in range(len(ids))]:
                    issue("SHAPE")
                else:
                    new_problems[ref] = ids
            elif section == "answers":
                parts = problem(x.get("problem"), "problem")
                existing = known_answers.get(ref)
                found, observed, scored = [], [], {}
                if ref.startswith("A/") and existing is None:
                    unknown(ref, "ref", "A/")
                if existing and isinstance(x.get("problem"), str) and x["problem"].startswith("P/") and existing[1] != x["problem"]:
                    issue("CONTRADICTION", "problem")
                if (x.get("activity") not in spec["activities"] or "text" in x and not txt(x["text"]) or
                        "parts" in x and not isinstance(x["parts"], list) or len(rows(x.get("parts"))) > 24 or
                        "origin" in x and x["origin"] not in ("handwriting", "chat_text", "other", "unknown")):
                    issue("SHAPE")
                if x.get("confidence") is not None and not (num(x["confidence"]) and 0 <= x["confidence"] <= 100):
                    issue("SHAPE", "confidence")
                if x.get("minutes") is not None and not (num(x["minutes"]) and 0 < x["minutes"] <= 600):
                    issue("SHAPE", "minutes")
                if x.get("answered_at") is not None and not timestamp(x["answered_at"]):
                    issue("SHAPE", "answered_at")
                c = x.get("conditions")
                if c is not None:
                    if not isinstance(c, dict):
                        issue("SHAPE", "conditions")
                    else:
                        level, shown = c.get("reference"), c.get("shown")
                        if (any(c.get(k) is not None and type(c[k]) is not bool for k in ("hint", "method_cued", "closed")) or
                                level is not None and not (num(level) and int(level) == level and 0 <= level <= 5) or
                                c.get("familiarity") is not None and c["familiarity"] not in ("unseen", "seen", "unknown") or
                                shown is not None and (not isinstance(shown, list) or not distinct(shown) or any(y not in ("statement", "ability_name", "method", "hint", "solution", "quality", "generation_reason", "unknown") for y in shown))):
                            issue("SHAPE", "conditions")
                        if (type(level) is not bool and level == 0 and c.get("hint") is True or
                                c.get("closed") is True and (x.get("activity") != "immediate_reproduction" or num(level) and level > 0 or c.get("hint") is True)):
                            issue("CONTRADICTION", "conditions")
                for j, p in enumerate(rows(x.get("parts"))):
                    path = f"parts[{j}]"
                    p = obj(p)
                    pid, mark, quote = p.get("id"), p.get("mark"), p.get("quote")
                    if not txt(pid, 200) or p.get("work") not in spec["workStates"] or mark not in spec["marks"]:
                        issue("SHAPE", path)
                        continue
                    if pid in found:
                        issue("DUPLICATE", path + ".id")
                    if parts is not None and pid not in parts:
                        issue("ID", path + ".id")
                    found.append(pid)
                    if (quote is not None and not txt(quote, 2400) or "finding" in p and not txt(p["finding"], 700) or
                            "error" in p and p["error"] not in ("none", "K", "W", "N", "C") or
                            p.get("error") == "K" and not txt(p.get("k_evidence"), 500) or
                            p.get("concept_focus") is not None and p["concept_focus"] not in spec["conceptFocus"]):
                        issue("SHAPE", path)
                    if mark in observed_marks:
                        if p["work"] != "submitted" or not txt(quote, 2400) or not txt(p.get("finding"), 700) or x.get("origin") == "unknown" or mark == "correct" and p.get("error") not in (None, "none"):
                            issue("CONTRADICTION", path)
                        else:
                            observed.append(pid)
                    if mark == "blank_zero" and (p["work"] != "not_started" or quote is not None or not points(p.get("points")) or p["points"][0] != 0):
                        issue("CONTRADICTION", path)
                    if p["work"] == "not_started" and quote is not None and mark != "blank_zero":
                        issue("CONTRADICTION", path + ".quote")
                    if "points" in p:
                        if not points(p["points"]) or mark not in (*observed_marks, "blank_zero"):
                            issue("SCORE", path + ".points")
                        else:
                            scored[pid] = p["points"]
                if x.get("grade") is not None:
                    grade = obj(x["grade"])
                    selected, total = rows(grade.get("parts")), grade.get("points")
                    if (not points(total) or not selected or not distinct(selected) or
                            any(not isinstance(i, str) or i not in observed and i not in scored for i in selected) or
                            any(i not in selected for i in scored)):
                        issue("SCORE", "grade")
                    else:
                        for k in (0, 1):
                            subtotal = sum(scored.get(i, (0, 0))[k] for i in selected)
                            if subtotal > total[k] + .001 or len(scored) == len(selected) and abs(subtotal-total[k]) > .001:
                                issue("SCORE", "grade.points")
                                break
                if "change_reason" in x and not txt(x["change_reason"], 1200):
                    issue("SHAPE", "change_reason")
                if "resume" in x and x["resume"] not in lookup.get("resume", []):
                    unknown(x["resume"], "resume", "W/")
                if "repair" in x:
                    r = obj(x["repair"])
                    if r.get("ability_id") not in abilities or not txt(r.get("target"), 400) or not txt(r.get("guidance"), 1200) or r.get("unconfirmed") is not None and not txt(r["unconfirmed"], 450):
                        issue("SHAPE", "repair")
                if "quality" in x:
                    q = obj(x["quality"])
                    p = obj(q.get("problem"))
                    checks = obj(p.get("checks"))
                    if (not timestamp(q.get("presented_at")) or not rows(q.get("abilities")) or any(i not in abilities for i in q["abilities"]) or
                            not timestamp(p.get("checked_at")) or not txt(p.get("generator_pass_id"), 120) or not txt(p.get("validator_pass_id"), 120) or
                            any(type(obj(checks.get(k)).get("pass")) is not bool or not txt(obj(checks.get(k)).get("evidence"), 800) for k in spec["qualityChecks"])):
                        issue("SHAPE", "quality")
                if x.get("inspired_by") is not None:
                    link(x["inspired_by"], "inspired_by", prior=True)
                if x.get("comparison") is not None:
                    link(x["comparison"], "comparison", observed=True, prior=True)
                    c = obj(x["comparison"])
                    if not txt(c.get("why"), 500) or c.get("part_here") not in observed or "structure_difference" in c and not txt(c["structure_difference"], 900):
                        issue("SHAPE", "comparison")
                if "trace" in x:
                    trace = obj(x["trace"])
                    if not txt(trace.get("first"), 200) or any(k in trace and not isinstance(trace[k], list) for k in ("affected", "independent")):
                        issue("SHAPE", "trace")
                    else:
                        ids = [trace["first"], *rows(trace.get("affected")), *rows(trace.get("independent"))]
                        if not distinct(ids) or any(not any(obj(p).get("id") == i and p.get("mark") in ("incorrect", "partial") for p in rows(x.get("parts"))) for i in ids):
                            issue("CONTRADICTION", "trace")
                if not found and not txt(x.get("text")):
                    issue("SHAPE", "parts")
                if not any(e["severity"] == "error" and not re.search(r"\\.(inspired_by|comparison)(\\.|$)", e["path"]) for e in errors[previous:]):
                    new_answers[ref] = [ref, x.get("problem"), found, observed]
            elif section == "ongoing":
                parts = problem(x.get("problem"), "problem")
                if (not txt(x.get("next"), 1200) or "text" in x and not txt(x["text"]) or
                        "part" in x and (not txt(x["part"], 200) or parts is not None and x["part"] not in parts) or
                        "after" in x and not txt(x["after"], 160) or "guidance" in x and not txt(x["guidance"]) or
                        "change_reason" in x and not txt(x["change_reason"], 1200) or
                        "state" in x and x["state"] not in ("presented", "writing", "awaiting_grade", "partly_graded", "awaiting_retry")):
                    issue("SHAPE")
                if "resume" in x and x["resume"] not in lookup.get("resume", []):
                    unknown(x["resume"], "resume", "W/")
                after = x.get("after")
                if "after" in x and (not isinstance(after, str) or after not in new_answers and after not in known_answers and after not in declared and not temp.fullmatch(after)):
                    unknown(after, "after", "A/")
            elif section == "coaching":
                period = x.get("period")
                if (not txt(x.get("text")) or "kind" in x and x["kind"] not in ("theory", "repair", "integration", "retention", "exam", "four_week") or
                        x.get("minutes") is not None and not (num(x["minutes"]) and x["minutes"] > 0) or
                        "period" in x and (not isinstance(period, list) or len(period) != 2 or not all(map(day, period)) or period[0] > period[1])):
                    issue("SHAPE", "text")
                if "topic" in x and x["topic"] not in topics:
                    issue("ID", "topic")
                if "problem" in x:
                    problem(x["problem"], "problem")
            elif section == "updates":
                if x.get("ability") not in abilities:
                    issue("ID", "ability")
                if "topic" in x and x["topic"] not in topics:
                    issue("ID", "topic")
                sources, checked = rows(x.get("evidence")), obj(x.get("checked_by"))
                if (x.get("stage") not in spec["stages"] or x.get("use") not in ("working", "formal") or
                        not txt(x.get("why"), 1200) or not 1 <= len(sources) <= 8 or
                        "setting" in x and not txt(x["setting"], 400) or "replaces" in x and not txt(x["replaces"], 160) or
                        "checked_by" in x and (checked.get("method") not in ("official_solution", "independent_derivation", "numerical_check") or not txt(checked.get("reference"), 700))):
                    issue("SHAPE")
                for j, e in enumerate(sources):
                    link(e, f"evidence[{j}]", observed=True)
                    if "outcome" in obj(e) and e["outcome"] not in ("success", "failure", "partial", "uncertain"):
                        issue("SHAPE", f"evidence[{j}].outcome")
            else:
                action, sources = x.get("action"), rows(x.get("evidence"))
                if (action not in ("add", "change", "complete", "cancel") or action == "add" and
                        (not txt(x.get("task"), 1200) or not temp.fullmatch(ref) or not sources and "topic" not in x and "goal" not in x) or
                        action != "add" and not txt(x.get("why"), 1200) or x.get("due") is not None and not day(x["due"]) or
                        "evidence" in x and (not isinstance(x["evidence"], list) or len(sources) > 8) or
                        "task" in x and not txt(x["task"], 1200) or "success" in x and not txt(x["success"], 1000) or
                        "goal" in x and x["goal"] not in ("math_goal", "final_goal")):
                    issue("SHAPE")
                if action != "add" and ref not in lookup["reviews"]:
                    unknown(ref, "ref", "R/")
                if "topic" in x and x["topic"] not in topics:
                    issue("ID", "topic")
                for j, e in enumerate(sources):
                    link(e, f"evidence[{j}]", observed=True)
                if action == "complete" and not txt(obj(x.get("done")).get("activity"), 160):
                    link(x.get("done"), "done", observed=True)
    return result("needs_review" if any(e["severity"] == "error" for e in errors) else "device_required" if errors else "checked")


ENGINE = ""
SCHEMA = ""
COACHING = ""
EXPECTED = "30e6ed88c665cac581a67db74f65fd694486011bfdee5c596c6675dff3c5bfc3"

def main(args):
    code = gzip.decompress(base64.b64decode(ENGINE))
    if hashlib.sha256(code).hexdigest() != EXPECTED:
        raise ValueError("Verifier bytes do not match the build")
    schema = json.loads(gzip.decompress(base64.b64decode(SCHEMA)))
    if args == ["--schema"]:
        print(json.dumps(schema, ensure_ascii=True, indent=2))
        return 0
    coaching = json.loads(gzip.decompress(base64.b64decode(COACHING)))
    if args == ["--coaching-schema"]:
        print(json.dumps(coaching["schema"], ensure_ascii=True, indent=2))
        return 0
    if len(args) == 2:
        try:
            morning = json.loads(Path(args[0]).read_bytes().decode("utf-8-sig"))
            if isinstance(morning, dict) and morning.get("format") == coaching["morningFormat"]:
                raw = Path(args[1]).read_bytes()
                report = coaching_check(morning, raw.decode("utf-8-sig"), EXPECTED, coaching)
                report["result_sha256"] = hashlib.sha256(raw).hexdigest()
                report["runtime_sha256"] = EXPECTED
                print(json.dumps(report, ensure_ascii=True))
                return {"checked": 0, "invalid": 1}.get(report["status"], 2)
        except (ValueError, TypeError, OSError, KeyError, IndexError) as error:
            print(json.dumps({"status":"invalid","code":"FORMAT","reason":str(error)}))
            return 1
    node = shutil.which("node") or shutil.which("nodejs")
    if not node:
        # A Python-only environment may have jsonschema. No installation or
        # network is required. Partial verification never returns success.
        try:
            import jsonschema
        except ImportError:
            print(json.dumps({"status": "not_executed", "reason": "Full runtime unavailable. Use the app preview."}))
            return 3
        if len(args) != 2:
            return 3
        morning = json.loads(Path(args[0]).read_bytes().decode("utf-8-sig"))
        info = morning.get("preflight", {})
        if info.get("runtime_sha256", EXPECTED) != EXPECTED or info.get("version", schema["$id"].split(":")[-1]) != schema["$id"].split(":")[-1]:
            print(json.dumps({"status": "invalid", "code": "TOOL_VERSION"}))
            return 1
        raw = Path(args[1]).read_bytes()
        result = json.loads(raw.decode("utf-8-sig"))
        errors = [{"path": list(e.absolute_path), "code": e.validator} for e in jsonschema.Draft7Validator(schema).iter_errors(result)]
        print(json.dumps({"status":"structure_only","issues":errors[:80], "result_sha256":hashlib.sha256(raw).hexdigest(),
                          "reason":"Raw structure only. Compatibility conversion, references, and scoring require the app preview."}))
        return 2
    with tempfile.TemporaryDirectory() as directory:
        script = Path(directory) / "stat1-preflight.cjs"
        script.write_bytes(code)
        return subprocess.run([node, "--disallow-code-generation-from-strings", str(script), *args], check=False).returncode

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
`;export{n as source};
